import{f as i,o as a,c as e,ah as o}from"./chunks/framework.5bt9HFMa.js";const g=JSON.parse('{"title":"android原生开发知识笔记","description":"本笔记系统梳理了Android原生开发的知识体系，从系统基础到应用组件，再到UI开发与网络通信，覆盖了Android开发的方方面面。","frontmatter":{"title":"android原生开发知识笔记","description":"本笔记系统梳理了Android原生开发的知识体系，从系统基础到应用组件，再到UI开发与网络通信，覆盖了Android开发的方方面面。","date":"2026-01-15T00:00:00.000Z","tags":["android","原生开发","kotlin","MVVM","jetpack compose"]},"headers":[],"relativePath":"series/android原生开发/index.md","filePath":"series/android原生开发/index.md","lastUpdated":1777733211000}'),r={name:"series/android原生开发/index.md"};function t(n,l,s,u,d,h){return a(),e("div",null,l[0]||(l[0]=[o('<h1 id="📱-android原生开发知识笔记-——-体系化梳理与渐进式技术演进" tabindex="-1">📱 Android原生开发知识笔记 —— 体系化梳理与渐进式技术演进 <a class="header-anchor" href="#📱-android原生开发知识笔记-——-体系化梳理与渐进式技术演进" aria-label="Permalink to &quot;📱 Android原生开发知识笔记 —— 体系化梳理与渐进式技术演进&quot;">​</a></h1><h2 id="一、android系统基础与架构演进" tabindex="-1">一、Android系统基础与架构演进 <a class="header-anchor" href="#一、android系统基础与架构演进" aria-label="Permalink to &quot;一、Android系统基础与架构演进&quot;">​</a></h2><h3 id="_1-1-系统底层机制" tabindex="-1"><a href="./1.1系统底层机制.html">1.1 系统底层机制</a> <a class="header-anchor" href="#_1-1-系统底层机制" aria-label="Permalink to &quot;[1.1 系统底层机制](1.1%E7%B3%BB%E7%BB%9F%E5%BA%95%E5%B1%82%E6%9C%BA%E5%88%B6.md)&quot;">​</a></h3><ul><li><strong>[基础] 进程与内存管理</strong><ul><li>Linux内核层交互、Zygote进程孵化机制</li><li>Android 16内存压缩优化、后台进程限制策略（Android 12+延续）</li></ul></li><li><strong>[核心] 应用沙箱与安全边界</strong><ul><li>SELinux策略演进、应用隔离机制（从Dalvik到ART的变迁）</li></ul></li></ul><h3 id="_1-2-应用生命周期演进" tabindex="-1">1.2 应用生命周期演进 <a class="header-anchor" href="#_1-2-应用生命周期演进" aria-label="Permalink to &quot;1.2 应用生命周期演进&quot;">​</a></h3><ul><li><strong>[基础]</strong> 传统生命周期模型 <ul><li>基于四大组件的回调机制</li><li>配置变更（Configuration Change）对生命周期的影响</li></ul></li><li><strong>[核心]</strong> 现代生命周期管理 <ul><li>LifecycleOwner / LifecycleObserver 抽象</li><li>Android 15+ Predictive Back 对生命周期语义的扩展</li></ul></li></ul><h2 id="二、ui开发体系-从传统view到现代compose" tabindex="-1">二、UI开发体系：从传统View到现代Compose <a class="header-anchor" href="#二、ui开发体系-从传统view到现代compose" aria-label="Permalink to &quot;二、UI开发体系：从传统View到现代Compose&quot;">​</a></h2><h3 id="_2-1-传统view体系" tabindex="-1">2.1 传统View体系 <a class="header-anchor" href="#_2-1-传统view体系" aria-label="Permalink to &quot;2.1 传统View体系&quot;">​</a></h3><ul><li><strong>[基础] View系统核心机制</strong><ul><li>事件分发（dispatchTouchEvent/onInterceptTouchEvent/onTouchEvent）</li><li>绘制流程（Measure-Layout-Draw）、硬件加速原理</li></ul></li><li><strong>[核心] 传统布局优化</strong><ul><li>ConstraintLayout 2.1约束优化、布局层级扁平化策略</li><li>ListView/GridView缓存机制与RecyclerView过渡方案</li></ul></li></ul><h3 id="_2-2-现代compose体系" tabindex="-1">2.2 现代Compose体系 <a class="header-anchor" href="#_2-2-现代compose体系" aria-label="Permalink to &quot;2.2 现代Compose体系&quot;">​</a></h3><ul><li><strong>[核心] Jetpack Compose 1.9核心架构</strong><ul><li>声明式UI原理：重组机制（Recomposition）、智能跳过（Skipping）</li><li>状态管理：State/ViewModel集成、单向数据流架构</li></ul></li><li><strong>[前瞻] 高级Compose技术</strong><ul><li>动画系统：高性能90fps动画、手势与物理动画集成</li><li>跨平台实践：Compose Multiplatform多端代码共享（Android/Desktop/iOS）</li></ul></li></ul><h2 id="三、应用组件与通信机制" tabindex="-1">三、应用组件与通信机制 <a class="header-anchor" href="#三、应用组件与通信机制" aria-label="Permalink to &quot;三、应用组件与通信机制&quot;">​</a></h2><h3 id="_3-1-组件化架构演进" tabindex="-1">3.1 组件化架构演进 <a class="header-anchor" href="#_3-1-组件化架构演进" aria-label="Permalink to &quot;3.1 组件化架构演进&quot;">​</a></h3><ul><li><strong>[基础] 四大组件深度解析</strong><ul><li>Activity启动模式（standard/singleTop/singleTask/singleInstance）</li><li>Service绑定机制、前台服务优化（Android 9+限制）</li></ul></li><li><strong>[核心] 现代组件通信</strong><ul><li>Navigation Component 2.8：类型安全导航、深层链接处理</li><li>Hilt依赖注入：组件生命周期感知、ViewModel工厂</li></ul></li></ul><h3 id="_3-2-跨进程通信-ipc-技术栈" tabindex="-1">3.2 跨进程通信（IPC）技术栈 <a class="header-anchor" href="#_3-2-跨进程通信-ipc-技术栈" aria-label="Permalink to &quot;3.2 跨进程通信（IPC）技术栈&quot;">​</a></h3><ul><li><strong>[基础] 传统IPC方案</strong><ul><li>Binder机制原理、AIDL接口定义、Messenger轻量级通信</li></ul></li><li><strong>[前瞻] 现代IPC优化</strong><ul><li>Jetpack DataStore跨进程同步、WorkManager集群任务调度</li></ul></li></ul><h2 id="四、数据管理与持久化方案演进" tabindex="-1">四、数据管理与持久化方案演进 <a class="header-anchor" href="#四、数据管理与持久化方案演进" aria-label="Permalink to &quot;四、数据管理与持久化方案演进&quot;">​</a></h2><h3 id="_4-1-本地存储技术演进" tabindex="-1">4.1 本地存储技术演进 <a class="header-anchor" href="#_4-1-本地存储技术演进" aria-label="Permalink to &quot;4.1 本地存储技术演进&quot;">​</a></h3><ul><li><strong>[基础] 传统存储方案</strong><ul><li>SharedPreferences原理与缺陷、SQLiteOpenHelper基础操作</li><li>文件存储：内部/外部存储权限变迁（Scoped Storage适配）</li></ul></li><li><strong>[核心] 现代持久化方案</strong><ul><li>Room 3.0+：Kotlin协程支持、自动迁移、数据库加密</li><li>DataStore：Preferences DataStore vs Proto DataStore性能对比</li></ul></li></ul><h3 id="_4-2-数据层架构设计" tabindex="-1">4.2 数据层架构设计 <a class="header-anchor" href="#_4-2-数据层架构设计" aria-label="Permalink to &quot;4.2 数据层架构设计&quot;">​</a></h3><ul><li><strong>[核心] Repository模式实践</strong><ul><li>单一数据源原则、缓存策略（内存/磁盘/网络三级缓存）</li><li>Flow数据流统一：Room Flow + Retrofit Flow + Cache Flow整合</li></ul></li></ul><h2 id="五、网络通信与api集成" tabindex="-1">五、网络通信与API集成 <a class="header-anchor" href="#五、网络通信与api集成" aria-label="Permalink to &quot;五、网络通信与API集成&quot;">​</a></h2><h3 id="_5-1-网络层技术演进" tabindex="-1">5.1 网络层技术演进 <a class="header-anchor" href="#_5-1-网络层技术演进" aria-label="Permalink to &quot;5.1 网络层技术演进&quot;">​</a></h3><ul><li><strong>[基础] 传统网络方案</strong><ul><li>HttpURLConnection基础使用、Volley队列管理（历史项目维护）</li></ul></li><li><strong>[核心] 现代网络架构</strong><ul><li>Retrofit+OkHttp 5.0：动态URL、自动重试、WebSocket优化</li><li>Ktor客户端：Kotlin原生协程支持、多平台兼容</li></ul></li></ul><h3 id="_5-2-api集成最佳实践" tabindex="-1">5.2 API集成最佳实践 <a class="header-anchor" href="#_5-2-api集成最佳实践" aria-label="Permalink to &quot;5.2 API集成最佳实践&quot;">​</a></h3><ul><li><strong>[核心] RESTful API设计</strong><ul><li>分页处理（Paging 3.0集成）、错误统一处理、重试机制</li></ul></li><li><strong>[前瞻] AI API集成</strong><ul><li>设备端LLM调用（ML Kit 2026）、云端AI服务安全通信</li></ul></li></ul><h2 id="六、异步编程与线程管理演进" tabindex="-1">六、异步编程与线程管理演进 <a class="header-anchor" href="#六、异步编程与线程管理演进" aria-label="Permalink to &quot;六、异步编程与线程管理演进&quot;">​</a></h2><h3 id="_6-1-线程管理技术栈" tabindex="-1">6.1 线程管理技术栈 <a class="header-anchor" href="#_6-1-线程管理技术栈" aria-label="Permalink to &quot;6.1 线程管理技术栈&quot;">​</a></h3><ul><li><strong>[基础] 传统异步方案</strong><ul><li>Handler/Looper消息循环、AsyncTask生命周期问题</li><li>ThreadPoolExecutor自定义线程池</li></ul></li><li><strong>[核心] 现代异步架构</strong><ul><li>Kotlin协程2.2：Structured Concurrency、异常处理策略</li><li>Flow响应式编程：StateFlow/MutableStateFlow状态管理</li></ul></li></ul><h3 id="_6-2-后台任务管理" tabindex="-1">6.2 后台任务管理 <a class="header-anchor" href="#_6-2-后台任务管理" aria-label="Permalink to &quot;6.2 后台任务管理&quot;">​</a></h3><ul><li><strong>[核心] WorkManager 2.9</strong><ul><li>精确延迟任务、链式任务依赖、约束条件配置</li><li>与Foreground Service协作策略</li></ul></li></ul><h2 id="七、性能优化与质量保障" tabindex="-1">七、性能优化与质量保障 <a class="header-anchor" href="#七、性能优化与质量保障" aria-label="Permalink to &quot;七、性能优化与质量保障&quot;">​</a></h2><h3 id="_7-1-启动与运行时优化" tabindex="-1">7.1 启动与运行时优化 <a class="header-anchor" href="#_7-1-启动与运行时优化" aria-label="Permalink to &quot;7.1 启动与运行时优化&quot;">​</a></h3><ul><li><strong>[核心] 启动优化</strong><ul><li>冷/温/热启动分析、SplashScreen API 2.0（Android 12+）</li><li>异步初始化框架、类加载优化</li></ul></li><li><strong>[前瞻] AI驱动优化</strong><ul><li>Android 16预测性资源加载、功耗自适应调度</li></ul></li></ul><h3 id="_7-2-质量保障体系" tabindex="-1">7.2 质量保障体系 <a class="header-anchor" href="#_7-2-质量保障体系" aria-label="Permalink to &quot;7.2 质量保障体系&quot;">​</a></h3><ul><li><strong>[核心] 性能监控</strong><ul><li>Android Studio Profiler 2026：Compose内存泄漏检测</li><li>Systrace/Perfetto深度分析、ANR根因定位</li></ul></li><li><strong>[基础] 测试金字塔</strong><ul><li>单元测试（JUnit5+MockK）、UI测试（Espresso/Compose Testing）</li></ul></li></ul><h2 id="八、安全架构与权限管理" tabindex="-1">八、安全架构与权限管理 <a class="header-anchor" href="#八、安全架构与权限管理" aria-label="Permalink to &quot;八、安全架构与权限管理&quot;">​</a></h2><h3 id="_8-1-权限系统演进" tabindex="-1">8.1 权限系统演进 <a class="header-anchor" href="#_8-1-权限系统演进" aria-label="Permalink to &quot;8.1 权限系统演进&quot;">​</a></h3><ul><li><strong>[基础] 传统权限模型</strong><ul><li>Android 6.0运行时权限、特殊权限（SYSTEM_ALERT_WINDOW）</li></ul></li><li><strong>[核心] 现代权限策略</strong><ul><li>Android 15+权限自动重置、位置权限粒度控制</li><li>权限申请最佳实践：上下文感知、渐进式申请</li></ul></li></ul><h3 id="_8-2-数据安全架构" tabindex="-1">8.2 数据安全架构 <a class="header-anchor" href="#_8-2-数据安全架构" aria-label="Permalink to &quot;8.2 数据安全架构&quot;">​</a></h3><ul><li><strong>[核心] 端到端安全</strong><ul><li>Keystore加密存储、BiometricPrompt生物认证</li><li>SSL Pinning防抓包、证书透明度（Certificate Transparency）</li></ul></li><li><strong>[前瞻] 隐私沙盒</strong><ul><li>Android 16隐私保护增强、广告ID替代方案</li></ul></li></ul><h2 id="九、现代应用架构设计" tabindex="-1">九、现代应用架构设计 <a class="header-anchor" href="#九、现代应用架构设计" aria-label="Permalink to &quot;九、现代应用架构设计&quot;">​</a></h2><h3 id="_9-1-架构模式演进" tabindex="-1">9.1 架构模式演进 <a class="header-anchor" href="#_9-1-架构模式演进" aria-label="Permalink to &quot;9.1 架构模式演进&quot;">​</a></h3><ul><li><strong>[基础] MVP/MVC模式</strong><ul><li>MVP解耦实践、MVC局限性分析</li></ul></li><li><strong>[核心] MVVM/MVI架构</strong><ul><li>ViewModel+StateFlow+Compose最佳实践</li><li>MVI单向数据流：Intent-&gt;State-&gt;Effect模式</li></ul></li></ul><h3 id="_9-2-模块化与动态化" tabindex="-1">9.2 模块化与动态化 <a class="header-anchor" href="#_9-2-模块化与动态化" aria-label="Permalink to &quot;9.2 模块化与动态化&quot;">​</a></h3><ul><li><strong>[核心] 组件化架构</strong><ul><li>模块拆分策略、ARouter路由框架、模块间通信</li><li>动态功能模块（DFM）：Play Feature Delivery实践</li></ul></li><li><strong>[前瞻] 动态化方案</strong><ul><li>Kotlin Multiplatform业务逻辑共享、热修复安全边界</li></ul></li></ul><h2 id="十、工程化与devops实践" tabindex="-1">十、工程化与DevOps实践 <a class="header-anchor" href="#十、工程化与devops实践" aria-label="Permalink to &quot;十、工程化与DevOps实践&quot;">​</a></h2><h3 id="_10-1-现代构建体系" tabindex="-1">10.1 现代构建体系 <a class="header-anchor" href="#_10-1-现代构建体系" aria-label="Permalink to &quot;10.1 现代构建体系&quot;">​</a></h3><ul><li><strong>[核心] Gradle的使用与优化</strong><ul><li>配置缓存（Configuration Cache）、版本目录（Version Catalog）</li><li>KSP替代kapt：注解处理器性能提升40%</li></ul></li><li><strong>[前瞻] 构建云化</strong><ul><li>分布式构建（Bazel集成）、CI/CD流水线优化</li></ul></li></ul><h3 id="_10-2-质量门禁体系" tabindex="-1">10.2 质量门禁体系 <a class="header-anchor" href="#_10-2-质量门禁体系" aria-label="Permalink to &quot;10.2 质量门禁体系&quot;">​</a></h3><ul><li><strong>[核心] 代码质量保障</strong><ul><li>Detekt/Ktlint代码规范、SonarQube质量门禁</li><li>Baseline Profiles启动性能提升</li></ul></li><li><strong>[基础] 发布流程</strong><ul><li>AAB格式优势、Play Console发布策略</li></ul></li></ul>',51)]))}const b=i(r,[["render",t]]);export{g as __pageData,b as default};
